mapper.select:
SELECT

FROM (
    SELECT candidate.*
    FROM purchase_requests candidate
    WHERE candidate.applicant_id = #{applicantId}
    ORDER BY candidate.updated_at DESC, candidate.id DESC
    LIMIT #{limit}
) pr

ORDER BY pr.updated_at DESC, pr.id DESC

SELECT
    COUNT(*)::BIGINT AS pending_count,
    COUNT(*) FILTER (
        WHERE pr.desired_delivery_date < #{currentDate}
    )::BIGINT AS overdue_count
FROM purchase_requests pr
JOIN approver_department_scopes scope
  ON scope.department_id = pr.department_id
 AND scope.user_id = #{approverId}
WHERE pr.status = 'SUBMITTED'
